// Rekap penjualan hari ini
const rows = $input.all();
const today = new Date().toISOString().slice(0, 10);

let totalOrder = 0;
let totalPendapatan = 0;
let totalItem = 0;
const perProduk = {};

for (const r of rows) {
  const j = r.json;
  const tgl = String(j['Tanggal'] || j['tanggal'] || '').slice(0, 10);
  if (tgl !== today) continue;

  totalOrder++;
  const total = Number(j['Total'] || j['total'] || 0);
  totalPendapatan += total;
  const qty = Number(j['Jumlah'] || j['jumlah'] || 1);
  totalItem += qty;

  const produk = String(j['Produk'] || j['produk'] || 'Lainnya');
  if (!perProduk[produk]) perProduk[produk] = { qty: 0, pendapatan: 0 };
  perProduk[produk].qty += qty;
  perProduk[produk].pendapatan += total;
}

const rupiah = n => 'Rp ' + Number(n).toLocaleString('id-ID');

let pesan = '📊 LAPORAN PENJUALAN HARIAN\n';
pesan += 'Tanggal: ' + today + '\n';
pesan += '━━━━━━━━━━━━━━━━━━\n\n';
pesan += '🛒 Total Order   : ' + totalOrder + '\n';
pesan += '📦 Total Item    : ' + totalItem + '\n';
pesan += '💰 Total Pendapatan: ' + rupiah(totalPendapatan) + '\n\n';

if (Object.keys(perProduk).length > 0) {
  pesan += '📌 PRODUK TERJUAL\n';
  const sorted = Object.entries(perProduk).sort((a, b) => b[1].pendapatan - a[1].pendapatan);
  for (const [nama, d] of sorted) {
    pesan += '• ' + nama + ' — ' + d.qty + ' pcs (' + rupiah(d.pendapatan) + ')\n';
  }
} else {
  pesan += 'Belum ada order hari ini.';
}

return [{ json: { laporan: pesan, total_order: totalOrder, total_pendapatan: totalPendapatan } }];
